from AlgorithmImports import *


class StrategySystemAlgorithm(QCAlgorithm):

    SMA_PERIOD = 200
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_has_lot = False
        self.strategy_b_has_lot = False

    def OnData(self, data):
        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        current_spy_close = None
        current_spy_sma = None
        current_aapl_close = None
        current_aapl_rsi = None

        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            current_spy_close = spy_bar.Close
            self.spy_sma.Update(spy_bar.EndTime, current_spy_close)

            if self.spy_sma.IsReady:
                current_spy_sma = self.spy_sma.Current.Value

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            current_aapl_close = aapl_bar.Close

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif current_aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, current_aapl_close)

            if self.aapl_rsi.IsReady:
                current_aapl_rsi = self.aapl_rsi.Current.Value

        all_bars_present = all(
            data.Bars.ContainsKey(symbol)
            for symbol in self.symbols.values()
        )

        indicators_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and previous_spy_close is not None
            and previous_spy_sma is not None
            and current_spy_close is not None
            and current_spy_sma is not None
            and current_aapl_close is not None
            and current_aapl_rsi is not None
        )

        if all_bars_present and indicators_ready:
            spy_crosses_below_sma = (
                previous_spy_close >= previous_spy_sma
                and current_spy_close < current_spy_sma
            )
            spy_crosses_above_sma = (
                previous_spy_close <= previous_spy_sma
                and current_spy_close > current_spy_sma
            )

            if self.strategy_a_has_lot and spy_crosses_below_sma:
                self.Liquidate(self.spy)
                self.strategy_a_has_lot = False

            if self.strategy_b_has_lot and current_aapl_rsi > 60:
                self.Liquidate(self.aapl)
                self.strategy_b_has_lot = False

            if not self.strategy_a_has_lot and spy_crosses_above_sma:
                self.SetHoldings(self.spy, 0.40)
                self.strategy_a_has_lot = True

            if not self.strategy_b_has_lot and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 / current_aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.strategy_b_has_lot = True

        if current_spy_close is not None:
            self.previous_spy_close = current_spy_close
            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma

        if current_aapl_close is not None:
            self.previous_aapl_close = current_aapl_close

