from AlgorithmImports import *
from math import floor


class IndependentStrategySystem(QCAlgorithm):

    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}

        for ticker in self.tickers:
            security = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = security.Symbol

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD,
            MovingAverageType.Wilders
        )

        self.previous_spy_relation = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        self.spy_buy_pending = False
        self.spy_sell_pending = False
        self.aapl_buy_pending = False
        self.aapl_sell_pending = False

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = data.Bars[spy] if data.Bars.ContainsKey(spy) else None
        aapl_bar = data.Bars[aapl] if data.Bars.ContainsKey(aapl) else None

        spy_crossed_above = False
        spy_crossed_below = False
        current_spy_relation = None

        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            if self.spy_sma.IsReady:
                current_spy_relation = spy_bar.Close - self.spy_sma.Current.Value

                if self.previous_spy_relation is not None:
                    spy_crossed_above = (
                        self.previous_spy_relation <= 0
                        and current_spy_relation > 0
                    )
                    spy_crossed_below = (
                        self.previous_spy_relation >= 0
                        and current_spy_relation < 0
                    )

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            data.Bars.ContainsKey(self.symbols[ticker])
            for ticker in self.tickers
        )

        indicators_ready = (
            self.spy_sma.IsReady
            and self.previous_spy_relation is not None
            and self.aapl_rsi.IsReady
        )

        if all_bars_present and indicators_ready:
            # Evaluate every sell before any buy.
            if (
                self.spy_lot > 0
                and not self.spy_sell_pending
                and not self.spy_buy_pending
                and spy_crossed_below
            ):
                self.spy_sell_pending = True
                self.MarketOrder(
                    spy,
                    -self.spy_lot,
                    tag="STRATEGY_A_SELL"
                )

            if (
                self.aapl_lot > 0
                and not self.aapl_sell_pending
                and not self.aapl_buy_pending
                and self.aapl_rsi.Current.Value > 60
            ):
                self.aapl_sell_pending = True
                self.MarketOrder(
                    aapl,
                    -self.aapl_lot,
                    tag="STRATEGY_B_SELL"
                )

            if (
                self.spy_lot == 0
                and not self.spy_buy_pending
                and not self.spy_sell_pending
                and spy_crossed_above
            ):
                target_value = self.Portfolio.TotalPortfolioValue * 0.40
                quantity = floor(target_value / spy_bar.Close)

                if quantity > 0:
                    self.spy_buy_pending = True
                    self.MarketOrder(
                        spy,
                        quantity,
                        tag="STRATEGY_A_BUY"
                    )

            if (
                self.aapl_lot == 0
                and not self.aapl_buy_pending
                and not self.aapl_sell_pending
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = floor(20_000 / aapl_bar.Close)

                if quantity > 0:
                    self.aapl_buy_pending = True
                    self.MarketOrder(
                        aapl,
                        quantity,
                        tag="STRATEGY_B_BUY"
                    )

        if current_spy_relation is not None:
            self.previous_spy_relation = current_spy_relation

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if order.Tag == "STRATEGY_A_BUY":
                self.spy_lot += fill_quantity
            elif order.Tag == "STRATEGY_A_SELL":
                self.spy_lot = max(0, self.spy_lot + fill_quantity)
            elif order.Tag == "STRATEGY_B_BUY":
                self.aapl_lot += fill_quantity
            elif order.Tag == "STRATEGY_B_SELL":
                self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        terminal_statuses = [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

        if order_event.Status in terminal_statuses:
            if order.Tag == "STRATEGY_A_BUY":
                self.spy_buy_pending = False
            elif order.Tag == "STRATEGY_A_SELL":
                self.spy_sell_pending = False
            elif order.Tag == "STRATEGY_B_BUY":
                self.aapl_buy_pending = False
            elif order.Tag == "STRATEGY_B_SELL":
                self.aapl_sell_pending = False

from AlgorithmImports import *
from math import floor


class ExactStrategySystemAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.set_warm_up(
            max(self.SMA_PERIOD + 1, self.RSI_PERIOD + 1),
            Resolution.DAILY
        )

    def on_data(self, data: Slice):
        bars = data.bars

        spy_bar = bars[self.spy] if self.spy in bars else None
        aapl_bar = bars[self.aapl] if self.aapl in bars else None

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if spy_bar is not None:
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)
            current_spy_sma = (
                self.spy_sma.current.value if self.spy_sma.is_ready else None
            )
            self.previous_spy_close = spy_bar.close
            self.previous_spy_sma = current_spy_sma
        else:
            current_spy_sma = None

        if aapl_bar is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if any(symbol not in bars for symbol in self.symbols.values()):
            return

        if self.is_warming_up:
            return

        if (
            not self.spy_sma.is_ready
            or not self.aapl_rsi.is_ready
            or previous_spy_close is None
            or previous_spy_sma is None
            or current_spy_sma is None
            or self.previous_aapl_close is None
        ):
            return

        spy_close = spy_bar.close
        aapl_close = aapl_bar.close

        spy_crosses_above = (
            previous_spy_close <= previous_spy_sma
            and spy_close > current_spy_sma
        )
        spy_crosses_below = (
            previous_spy_close >= previous_spy_sma
            and spy_close < current_spy_sma
        )

        spy_quantity = int(self.portfolio[self.spy].quantity)
        aapl_quantity = int(self.portfolio[self.aapl].quantity)

        if spy_quantity > 0 and spy_crosses_below:
            self.market_order(
                self.spy, -spy_quantity, tag="Strategy A: cross below SMA"
            )

        if (
            aapl_quantity > 0
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(
                self.aapl, -aapl_quantity, tag="Strategy B: RSI above 60"
            )

        spy_quantity = int(self.portfolio[self.spy].quantity)
        aapl_quantity = int(self.portfolio[self.aapl].quantity)

        if spy_quantity == 0 and spy_crosses_above:
            target_quantity = self.calculate_order_quantity(self.spy, 0.40)
            if target_quantity > 0:
                self.market_order(
                    self.spy,
                    target_quantity,
                    tag="Strategy A: cross above SMA"
                )

        if aapl_quantity == 0 and self.aapl_red_streak >= 3:
            available_cash = self.portfolio.cash_book["USD"].amount
            if available_cash >= 20_000:
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self.market_order(
                        self.aapl,
                        quantity,
                        tag="Strategy B: three consecutive red days"
                    )

