        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue
            bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            self.spy_closes.append(bars["SPY"].Close)

        if "AAPL" in bars:
            aapl_close = bars["AAPL"].Close
            self.UpdateAaplRedStreak(aapl_close)
            self.UpdateAaplRsi(aapl_close)

        if len(bars) != len(self.symbols):
            return

        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close

        spy_crossed_above = False
        spy_crossed_below = False

        if len(self.spy_closes) == self.moving_average_period + 1:
            closes = list(self.spy_closes)
            previous_close = closes[-2]
            current_close = closes[-1]

            previous_average = sum(
                closes[:-1]
            ) / Decimal(self.moving_average_period)

            current_average = sum(
                closes[1:]
            ) / Decimal(self.moving_average_period)

            spy_crossed_above = (
                previous_close <= previous_average
                and current_close > current_average
            )
            spy_crossed_below = (
                previous_close >= previous_average
                and current_close < current_average
            )

        strategy_b_sell = (
            self.aapl_rsi is not None
            and self.aapl_rsi > Decimal("60")
        )

        if self.strategy_a_shares > 0 and spy_crossed_below:
