                )
        else:
            period = Decimal(self.rsi_period)
            self.aapl_average_gain = (
                self.aapl_average_gain * (period - Decimal("1")) + gain
            ) / period
            self.aapl_average_loss = (
                self.aapl_average_loss * (period - Decimal("1")) + loss
            ) / period

        if self.aapl_average_gain is not None:
