                self.aapl_rsi = Decimal("100")
            else:
                relative_strength = (
                    self.aapl_average_gain / self.aapl_average_loss
                )
                self.aapl_rsi = Decimal("100") - (
                    Decimal("100") /
                    (Decimal("1") + relative_strength)
                )

