from AlgorithmImports import *


class ParallelStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_ma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_ma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        self._synchronize_lots_after_splits(data)

        spy_crossed_above = False
        spy_crossed_below = False
        aapl_rsi_above_60 = False

        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            old_close = self.previous_spy_close
            old_ma = self.previous_spy_ma

            self.spy_ma.Update(spy_bar.EndTime, spy_bar.Close)
            current_ma = (
                float(self.spy_ma.Current.Value)
                if self.spy_ma.IsReady
                else None
            )

            if old_close is not None and old_ma is not None and current_ma is not None:
                spy_crossed_above = (
                    old_close <= old_ma and spy_bar.Close > current_ma
                )
                spy_crossed_below = (
                    old_close >= old_ma and spy_bar.Close < current_ma
                )

            self.previous_spy_close = spy_bar.Close
            self.previous_spy_ma = current_ma

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]

            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.aapl_rsi.IsReady:
                aapl_rsi_above_60 = self.aapl_rsi.Current.Value > 60

        if any(
            not data.Bars.ContainsKey(symbol)
            for symbol in self.symbols.values()
        ):
            return

        if (
            not self.spy_ma.IsReady
            or not self.aapl_rsi.IsReady
            or self.previous_spy_ma is None
            or self.previous_aapl_close is None
        ):
            return

        # Evaluate sells before buys.
        if (
            self.spy_lot > 0
            and not self._has_open_order(self.spy)
            and spy_crossed_below
        ):
            self.MarketOrder(
                self.spy, -self.spy_lot, tag="StrategyA"
            )

        if (
            self.aapl_lot > 0
            and not self._has_open_order(self.aapl)
            and aapl_rsi_above_60
        ):
            self.MarketOrder(
                self.aapl, -self.aapl_lot, tag="StrategyB"
            )

        if self.spy_lot == 0 and not self._has_open_order(self.spy):
            if spy_crossed_above:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(
                        self.spy, quantity, tag="StrategyA"
                    )

        if self.aapl_lot == 0 and not self._has_open_order(self.aapl):
            if self.aapl_red_streak >= 3:
                cash_required = 20_000
                if self.Portfolio.Cash >= cash_required:
                    close = data.Bars[self.aapl].Close
                    quantity = int(cash_required // close)
                    if quantity > 0:
                        self.MarketOrder(
                            self.aapl, quantity, tag="StrategyB"
                        )

    def OnOrderEvent(self, order_event):
        if order_event.FillQuantity == 0:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if order.Tag == "StrategyA":
            self.spy_lot = max(0, self.spy_lot + fill_quantity)
        elif order.Tag == "StrategyB":
            self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

    def _has_open_order(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

    def _synchronize_lots_after_splits(self, data):
        if data.Splits.ContainsKey(self.spy):
            split = data.Splits[self.spy]
            if split.Type == SplitType.SplitOccurred:
                self.spy_lot = max(
                    0, int(self.Portfolio[self.spy].Quantity)
                )

        if data.Splits.ContainsKey(self.aapl):
            split = data.Splits[self.aapl]
            if split.Type == SplitType.SplitOccurred:
                self.aapl_lot = max(
                    0, int(self.Portfolio[self.aapl].Quantity)
                )

