                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=20)
        self.spy_close_ma = deque(maxlen=2)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_change_count = 0
        self.rsi_initial_gain = 0.0
        self.rsi_initial_loss = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        self._adjust_lots_for_splits(data)

        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            self._update_spy_state(float(spy_bar.Close))

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            self._update_aapl_state(float(aapl_bar.Close))

        if not all(data.Bars.ContainsKey(symbol)
                   for symbol in self.symbols.values()):
            return

