            return

        spy_yesterday_close, spy_yesterday_ma = self.spy_close_ma[-2]
        spy_today_close, spy_today_ma = self.spy_close_ma[-1]
        aapl_close = float(data.Bars[self.aapl].Close)

        spy_crosses_below = (
            spy_yesterday_close >= spy_yesterday_ma
            and spy_today_close < spy_today_ma
        )
        spy_crosses_above = (
            spy_yesterday_close <= spy_yesterday_ma
            and spy_today_close > spy_today_ma
        )

        # Evaluate all sells before any buys.
        if self.spy_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crosses_above:
