            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            target_value = (
                Decimal("0.40") * Decimal(self.Portfolio.TotalPortfolioValue)
            )
            quantity = int(target_value // spy_close_today)

            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_required = Decimal("20000")
            available_cash = Decimal(self.Portfolio.Cash)

            if available_cash >= cash_required:
                quantity = int(cash_required // aapl_close_today)

                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.strategy_b_shares = quantity

